import{notFound}from"next/navigation";import{getServerContext}from"@/lib/context";import{resolveUserContext}from"@/server/services/AccessService";import{PERMISSIONS}from"@/types";import{VendorDocumentsPanel}from"@/components/vendor/VendorDocumentsPanel";
export default async function VendorDetailPage({params}:{params:Promise<{id:string}>}){const{id}=await params;const{supabase,societyId,wingId}=await getServerContext();const context=await resolveUserContext(societyId,wingId);const[{data:vendor},{data:documents},{data:performance}]=await Promise.all([supabase.from("vendors").select("id,vendor_code,name,vendor_type,contact_name,email,phone,address,gstin,pan,status,is_verified").eq("id",id).eq("society_id",societyId).single(),supabase.from("vendor_documents").select("id,document_type,title,document_number,issued_on,expires_on,file_name,file_size_bytes,status,version,rejection_reason,created_at").eq("vendor_id",id).eq("society_id",societyId).order("created_at",{ascending:false}),supabase.from("vendor_performance_reviews").select("id,overall_score,comments,reviewed_at").eq("vendor_id",id).eq("society_id",societyId).order("reviewed_at",{ascending:false})]);if(!vendor)notFound();const score=performance?.[0]?.overall_score;return <div className="page-container"><div className="page-header"><div><p className="font-mono text-sm text-[#10B981]">{vendor.vendor_code}</p><h1 className="text-3xl font-bold text-text-primary">{vendor.name}</h1><p className="mt-1 text-sm text-[#9CA3AF]">{vendor.vendor_type} · {vendor.status} · {vendor.is_verified?"Verified":"Verification pending"}</p></div></div><div className="mb-5 grid gap-4 md:grid-cols-3"><div className="queue-section p-4"><p className="text-xs text-[#6B7280]">Contact</p><p className="text-sm text-text-primary">{vendor.contact_name??"—"}</p><p className="text-xs text-[#9CA3AF]">{vendor.email??vendor.phone??"—"}</p></div><div className="queue-section p-4"><p className="text-xs text-[#6B7280]">Registration</p><p className="text-sm text-text-primary">GST {vendor.gstin??"—"}</p><p className="text-xs text-[#9CA3AF]">PAN {vendor.pan??"—"}</p></div><div className="queue-section p-4"><p className="text-xs text-[#6B7280]">Performance</p><p className="text-sm text-text-primary">{score??"Not rated"}{score?" / 5":""}</p><p className="text-xs text-[#9CA3AF]">{performance?.length??0} review(s)</p></div></div><VendorDocumentsPanel societyId={societyId} vendorId={vendor.id} documents={documents??[]} canUpload={context.isPlatformAdmin||context.permissions.has(PERMISSIONS.VENDOR_UPDATE)} canReview={!context.isPlatformAdmin&&context.roleName==="Society Admin"&&!context.wingId&&context.permissions.has(PERMISSIONS.VENDOR_VERIFY)}/></div>}
